define('taoBackOffice/controller/tree/view',['layout/actions/binder', 'uri', 'jquery', 'context', 'helpers', 'taoBackOffice/treeRender'], function (binder, uri, $, context, helpers, treeRender) {
  'use strict';
  var itemRunnerController = {
    start: function start() {
      $('.tree-container').each(function (i, obj) {
        var $container = $(obj);
        var uri = $container.data('id');
        $.post(helpers._url('getTree', 'Trees', 'taoBackOffice'), {
          uri: uri
        }, function (treeData) {
          var $parent = $container.closest('.content-block');
          var resizeContainer = function resizeContainer() {
            $container.height($parent.height() - $parent.find('.panel').eq(0).outerHeight());
            $container.width($parent.width());
          };
          $(window).on('resize', resizeContainer);
          resizeContainer();
          treeRender.init($container[0], treeData);
          treeRender.run();
        });
      });
    }
  };
  return itemRunnerController;
});
