define('taoBackOffice/controller/list/index',['jquery', 'i18n', 'uri', 'util/url', 'ui/feedback', 'ui/dialog/confirm', 'layout/section', 'core/request', 'tpl!taoBackOffice/tpl/tooltip', 'ui/tooltip', 'css!taoBackOfficeCss/list'], function ($, __, Uri, urlUtil, feedback, dialogConfirm, section, request, tooltipTpl, tooltip) {
  'use strict';

  function findListContainer(uri) {
    return $("#list-data_".concat(uri));
  }
  function clearUri(value) {
    return value.replace(/^list-element_[0-9]+_/, '');
  }
  function createEditUriCheckbox(id) {
    var $checkbox = $('<input>').attr('type', 'checkbox').attr('id', id).attr('data-testid', 'editUriCheckbox').change(handleEditCheckboxStateChange);
    var $label = $('<label>').attr('for', id).text(__('Edit URI')).focus();
    return $('<span>').addClass('lft edit-uri').append($checkbox, $label);
  }
  function createButton(title, icon) {
    var position = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : 'rgt';
    var $btn = $('<button>', {
      'class': "btn-info small ".concat(position, " icon-").concat(icon),
      'data-testid': "".concat(icon, "ElementButton"),
      title: __(title)
    });
    return $btn;
  }
  function transformListElement($element) {
    return createListElement($element.attr('id'), $element.text());
  }
  function createNewListElement(elementId) {
    return createListElement("list-element_".concat(elementId, "_"));
  }
  function createListElement(name) {
    var value = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : '';
    var uri = Uri.decode(clearUri(name));
    return $("<div class='list-element'>\n            <div class='list-element'>\n                <div class='list-element__input-container'>\n                    <input type='text' name='".concat(name, "' value='").concat(value, "' data-testid='elementNameInput' data-former-value='").concat(value, "'/>\n                    <div class='list-element__input-container__uri'>\n                        <label for='uri_").concat(name, "' class='title'>URI</label>\n                        <input id='uri_").concat(name, "' type='text' name='uri_").concat(name, "' value='").concat(uri, "' data-former-value='").concat(uri, "' data-testid='elementUriInput'>\n                    </div>\n                </div>\n                <span class='icon-checkbox-crossed list-element-delete-btn' data-testid='deleteElementButton'>\n            </div>\n        </div>"));
  }
  function handleEditCheckboxStateChange() {
    findListContainer($(this).attr('id')).toggleClass('with-uri');
  }
  function showElementsEditControls($listContainer) {
    $listContainer.find('span.list-element').replaceWith(function () {
      return transformListElement($(this));
    });
  }
  function handleEditList(targetUri) {
    var uri = getUriValue(targetUri);
    var $listContainer = findListContainer(uri);
    var list = $listContainer.find('ol');
    var offset = list.children('[id^=list-element]').length;
    var batchSize = 100;
    var totalItems = 0;
    var maxItems = 1000;
    if ($('#data-max-items').length !== 0) {
      maxItems = parseInt($('#data-max-items').val(), 10);
    }
    function isLimitReached() {
      return totalItems >= maxItems;
    }
    loadListElements(uri, offset, batchSize).then(newListData => {
      extendListWithNewElements(newListData, $listContainer);
      var saveUrl = urlUtil.route('saveLists', 'Lists', 'taoBackOffice');
      var delEltUrl = urlUtil.route('removeListElement', 'Lists', 'taoBackOffice');
      var $listForm = $listContainer.find('form');
      var $listTitleBar = $listContainer.find('.container-title h6');
      var $listToolBar = $listContainer.find('.data-container-footer').empty();
      var $tooltip = $(tooltipTpl({
        message: __('Maximum allowed number of elements is reached, you cannot add more elements. Please contact your administrator.')
      }));
      var $listSaveBtn;
      var $listNewBtn;
      totalItems = newListData.totalCount;
      function toggleAddButton(isDisabled) {
        $listNewBtn.attr('disabled', isDisabled);
        $tooltip.toggleClass('tooltip-hidden', !isDisabled);
      }
      function hasChangedListItemValue(form, item) {
        var formerValue = $('[name="' + item.name + '"]', form).data('formerValue');
        var formerURI = $('[name="uri_' + item.name + '"]', form).data('formerValue');
        var newURI = $('[name="uri_' + item.name + '"]', form).val();
        if (formerURI.trim() == '') {
          return true;
        }
        return formerValue != item.value || formerURI != newURI;
      }
      function hasChangedListItemURI(form, item) {
        var cleanName = item.name.substring(4);
        var formerURI = $('[name="' + item.name + '"]', form).data('formerValue');
        var formerValue = $('[name="' + cleanName + '"]', form).data('formerValue');
        var newValue = $('[name="' + cleanName + '"]', form).val();
        if (formerURI.trim() == '') {
          return true;
        }
        return formerValue != newValue || formerURI != item.value;
      }
      function listItemHasChanged(form, item) {
        if (!item.hasOwnProperty('name') || !item.hasOwnProperty('value')) {
          return true;
        }
        if (item.name.startsWith('list-element_')) {
          return hasChangedListItemValue(form, item);
        } else if (item.name.startsWith('uri_list-element_')) {
          return hasChangedListItemURI(form, item);
        }
        return true;
      }
      if (!$listForm.length) {
        var nextElementId = totalItems;
        $listForm = $('<form>');
        $listContainer.wrapInner($listForm);
        $listContainer.find('form').append("<input type='hidden' name='uri' value='".concat(uri, "' />"));
        var $labelEdit = $("<input type='text' name='label' value='' data-testid='listNameInput' />").val($listTitleBar.text());
        var $listNewContainer = $('<div></div>', {
          'class': 'add-button-container'
        });
        $listTitleBar.closest('.container-title').html($labelEdit);
        $labelEdit.focus();
        showElementsEditControls($listContainer);
        $listSaveBtn = createButton(__('Save list'), 'save');
        $listSaveBtn.on('click', function () {
          var form = $(this).closest('form');
          $.postJson(saveUrl, form.serializeArray().filter(item => listItemHasChanged(form, item)), response => {
            if (response.saved) {
              feedback().success(__('List saved'));
              section.get('taoBo_list').loadContentBlock(urlUtil.route('index', 'Lists', 'taoBackOffice'));
            } else {
              var errors = (response.errors || []).length ? "<ul><li>".concat(response.errors.join('</li><li>'), "</li></ul>") : '';
              feedback().error("".concat(__('List not saved')).concat(errors), {
                encodeHtml: false
              });
            }
          });
          return false;
        });
        $listNewBtn = createButton('New element', 'add');
        $listNewBtn.click(function () {
          var $list = $(this).closest('form').find('ol');
          totalItems = totalItems + 1;
          toggleAddButton(isLimitReached());
          $list.append($('<li>').append(createNewListElement(nextElementId++))).closest('.container-content').scrollTop($list.height());
          return false;
        });
        $listNewContainer.append($listNewBtn, $tooltip);
        $listToolBar.append($listSaveBtn, $listNewContainer, createEditUriCheckbox(uri));
        tooltip.lookup($listNewContainer);
        toggleAddButton(isLimitReached());
      }
      $listContainer.on('click', '.list-element-delete-btn', function () {
        var $element = $(this).closest('li');
        var $input = $element.find('input:text');
        var eltUri = clearUri($input.attr('name'));
        var deleteLocalElement = () => {
          $element.remove();
          totalItems = totalItems - 1;
          toggleAddButton(isLimitReached());
          feedback().success(__('Element deleted'));
        };
        var deleteServerAndLocalElement = () => {
          $.postJson(delEltUrl, {
            uri: eltUri
          }, response => {
            if (response.deleted) {
              deleteLocalElement();
            } else {
              feedback().error(__('Element not deleted'));
            }
          });
        };
        var deleteElement = () => {
          if (eltUri) {
            deleteServerAndLocalElement();
          } else {
            deleteLocalElement();
          }
        };
        if ($input.val() === '') {
          deleteElement();
        } else {
          dialogConfirm(__('Please confirm you want to delete this list element.'), deleteElement);
        }
      });
    });
  }
  function handleCreateList($form) {
    var isRemoteListCreation = ($form.attr('action') || '').includes('remote');
    request({
      url: isRemoteListCreation ? urlUtil.route('remote', 'Lists', 'taoBackOffice') : urlUtil.route('index', 'Lists', 'taoBackOffice'),
      method: 'POST',
      data: isRemoteListCreation ? $form.serialize() : null
    }).then(response => {
      response.data.uri = Uri.encode(response.data.uri);
      addNewList(response.data, isRemoteListCreation);
    }).catch(function (err) {
      feedback().error(err.response.message || err);
    });
  }
  function addNewList(newList, isRemoteList) {
    var $newListContainer = createListContainer(newList, isRemoteList);
    addHandlerListeners($newListContainer);
    var containerIdentifier = isRemoteList ? '#panel-taoBo_remotelist' : '#panel-taoBo_list';
    $("".concat(containerIdentifier, " .data-container-wrapper")).append($newListContainer);
    if (!isRemoteList) {
      handleEditList(newList.uri);
    }
  }
  function handleDeleteList() {
    var delListUrl = urlUtil.route('removeList', 'Lists', 'taoBackOffice');
    var $btn = $(this);
    dialogConfirm(__('Please confirm you want to delete this list. This operation cannot be undone.'), function accept() {
      var uri = $btn.data('uri');
      var $list = $btn.parents('.data-container');
      $.postJson(delListUrl, {
        uri
      }, response => {
        if (response.deleted) {
          feedback().success(__('List deleted'));
          $list.remove();
        } else {
          feedback().error(__('List not deleted'));
        }
      });
    });
  }
  function handleReloadList() {
    var reloadListUrl = urlUtil.route('reloadRemoteList', 'Lists', 'taoBackOffice');
    var uri = $(this).data('uri');
    $.postJson(reloadListUrl, {
      uri
    }, response => {
      if (response.saved) {
        feedback().success(__('List reloaded'));
        section.get('taoBo_remotelist').loadContentBlock(urlUtil.route('remote', 'Lists', 'taoBackOffice'));
      } else {
        feedback().error(response.message || __('List failed to be reloaded'));
      }
    });
  }
  function addHandlerListeners($listContainer) {
    $listContainer.on('click', '.list-edit-btn', handleEditList);
    $listContainer.on('click', '.list-delete-btn', handleDeleteList);
    $listContainer.on('click', '.list-reload-btn', handleReloadList);
  }
  function createListContainer(newList, isRemoteList) {
    return $("<section id=\"list-data_".concat(newList.uri, "\" class=\"data-container list-container\">\n                <header class=\"container-title\">\n                    <h6>").concat(newList.label, "</h6>\n                </header>\n                <div class=\"container-content\" id=\"list-elements_").concat(newList.uri, "\">\n                    ").concat(renderListElements(newList, isRemoteList), "\n                </div>\n                <footer class=\"data-container-footer action-bar\">\n                    <button\n                        type=\"button\"\n                        title=\"").concat(isRemoteList ? __('Reload this list') : __('Edit this list'), "\"\n                        class=\"icon-reload ").concat(isRemoteList ? 'list-reload-btn' : 'list-edit-btn', " btn-info small rgt\"\n                        data-uri=\"").concat(newList.uri, "\"\n                    ></button>\n                    <button\n                        type=\"button\"\n                        title=\"").concat(__('Delete this list'), "\"\n                        class=\"icon-bin list-delete-btn btn-warning small rgt\"\n                        data-uri=\"").concat(newList.uri, "\"\n                    ></button>\n                </footer>\n            </section>"));
  }
  function renderListElements(newList, isRemoteList) {
    var list = newList.elements.map((element, index) => {
      return renderListElement(index, element.uri, element.label);
    });
    if (isRemoteList && newList.totalCount > newList.elements.length) {
      var newElementIndex = newList.elements.length + 1;
      list.push(renderListElement(newElementIndex, '', '...'));
    }
    return "<ol data-testid=\"elements\">".concat(list.join(''), "</ol>");
  }
  function renderListElement(index, uri, label) {
    return "<li id=\"list-element_".concat(index, "\">\n            <span class=\"list-element\" id=\"list-element_").concat(index, "_").concat(Uri.encode(uri), "\">").concat(label, "</span>\n        </li>");
  }
  function getUriValue(targetUri) {
    if (typeof targetUri === 'string') {
      return targetUri;
    } else if (targetUri.currentTarget) {
      return $(targetUri.currentTarget).data('uri');
    }
  }
  function handleLoadMore() {
    var $btn = $(this);
    var listUri = getUriValue($btn.data('uri'));
    var $listContainer = findListContainer(listUri);
    var offset = $listContainer.find('ol').children('[id^=list-element]').length;
    $btn.find('a').text('Loading...');
    $btn.find('.icon-loop').toggleClass('rotate');
    loadListElements(listUri, offset).then(newListData => {
      $btn.find('a').text('Load more');
      $btn.find('.icon-loop').toggleClass('rotate');
      extendListWithNewElements(newListData, $listContainer, listUri);
      if ($listContainer.find('form').length) {
        showElementsEditControls($listContainer);
      }
    });
  }
  function loadListElements(listUri, offset, limit) {
    var loadMoreUrl = urlUtil.route('getListElements', 'Lists', 'taoBackOffice');
    var res = new Promise(resolve => {
      $.getJSON(loadMoreUrl, {
        listUri,
        offset,
        limit
      }, response => {
        resolve(response.data);
      });
    });
    return res;
  }
  function extendListWithNewElements(_ref, listContainer) {
    var elements = _ref.elements,
      totalCount = _ref.totalCount;
    var $list = listContainer.find('ol');
    var offset = $list.children('[id^=list-element]').length;
    var buffer = '';
    for (var i = 0, id = '', len = elements.length; i < len; i++) {
      id = "list-element_".concat(offset++, "_");
      buffer += "<li id=".concat(id, "><span class='list-element' id='").concat(id).concat(elements[i].uri, "'>").concat(elements[i].label, "</span></li>");
    }
    $list.append(buffer).closest('.container-content').scrollTop($list.height());
    if (offset === totalCount) {
      listContainer.find('.pagination-container').hide();
    }
  }
  return {
    start() {
      $('.form-submitter').off('click').on('click', e => {
        e.preventDefault();
        handleCreateList($(e.target).closest('form'));
      });
      $('.list-edit-btn').click(handleEditList);
      $('.list-delete-btn').click(handleDeleteList);
      $('.list-reload-btn').click(handleReloadList);
      $('.load-more-btn').click(handleLoadMore);
    }
  };
});
